def apply_new_rule(grid_in):
    result = [row[:] for row in grid_in]

    # Horizontal
    for r in range(len(result)):
        cols = [c for c in range(len(result[0])) if result[r][c] == 2]
        if len(cols) >= 3:  # At least 3 twos
            for i in range(len(cols)-1):
                left, right = cols[i], cols[i+1]
                gap = right - left - 1  # Number of zeros between
                if gap >= 2:  # Gap of at least 2
                    for c in range(left+1, right):
                        result[r][c] = 1

    # Vertical
    for c in range(len(result[0])):
        rows = [r for r in range(len(result)) if result[r][c] == 2]
        if len(rows) >= 3:
