# Check if the WHOLE grid has horizontal/vertical reflection symmetry
def check_horizontal_symmetry(grid):
    """Check if grid is symmetric left-right"""
    height, width = len(grid), len(grid[0])
    for r in range(height):
        for c in range(width//2):
            if grid[r][c] != grid[r][width-1-c]:
                return False, f"Mismatch at ({r},{c}): {grid[r][c]} vs {grid[r][width-1-c]}"
    return True, "Symmetric"

def check_vertical_symmetry(grid):
    """Check if grid is symmetric up-down"""
    height, width = len(grid), len(grid[0])
    for r in range(height//2):
        for c in range(width):
            if grid[r][c] != grid[height-1-r][c]:
                return False, f"Mismatch at ({r},{c}): {grid[r][c]} vs {grid[height-1-r][c]}"
    return True, "Symmetric"

for name, grid in [("D1", demo1_in), ("D2", demo2_in)]:
    hs, hmsg = check_horizontal_symmetry(grid)
    vs, vmsg = check_vertical_symmetry(grid)
    print(f"{name}: horiz_sym={hs}, vert_sym={vs}")

